alter table public.kos_workflow_runs add column if not exists idempotency_key text;
create unique index if not exists kos_workflow_runs_idempotency on public.kos_workflow_runs(workspace_id,idempotency_key) where idempotency_key is not null;
create or replace function public.kos_create_workflow(target_workspace uuid, slug_value text, name_value text, definition_value jsonb) returns public.kos_workflow_definitions language plpgsql security definer set search_path=public as $$ declare actor uuid:=auth.uid(); created public.kos_workflow_definitions; begin if actor is null or not public.kos_has_role(target_workspace,array['owner','admin']::public.kos_workspace_role[]) then raise exception 'owner or admin role required'; end if; if btrim(name_value)='' or slug_value !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then raise exception 'valid name and kebab-case slug required'; end if; if jsonb_typeof(definition_value)<>'object' then raise exception 'workflow definition must be an object'; end if; insert into public.kos_workflow_definitions(workspace_id,slug,name,definition,status) values(target_workspace,slug_value,name_value,definition_value,'active') returning * into created; return created; end; $$;
create or replace function public.kos_queue_workflow(target_workspace uuid,target_workflow uuid,input_value jsonb,idempotency_key_value text) returns public.kos_workflow_runs language plpgsql security definer set search_path=public as $$ declare actor uuid:=auth.uid(); created public.kos_workflow_runs; begin if actor is null or not public.kos_has_role(target_workspace,array['owner','admin','member']::public.kos_workspace_role[]) then raise exception 'workspace write access required'; end if; if not exists(select 1 from public.kos_workflow_definitions where id=target_workflow and workspace_id=target_workspace and status='active') then raise exception 'active workflow not found in workspace'; end if; if btrim(idempotency_key_value)='' then raise exception 'idempotency key required'; end if; insert into public.kos_workflow_runs(workspace_id,workflow_id,status,input,initiated_by,idempotency_key) values(target_workspace,target_workflow,'queued',coalesce(input_value,'{}'),actor,idempotency_key_value) on conflict(workspace_id,idempotency_key) where idempotency_key is not null do update set idempotency_key=excluded.idempotency_key returning * into created; return created; end; $$;
revoke all on function public.kos_create_workflow(uuid,text,text,jsonb) from public,anon;
revoke all on function public.kos_queue_workflow(uuid,uuid,jsonb,text) from public,anon;
grant execute on function public.kos_create_workflow(uuid,text,text,jsonb) to authenticated;
grant execute on function public.kos_queue_workflow(uuid,uuid,jsonb,text) to authenticated;
